arguments.command:
cd /workspace && python - <<'EOF'
import attr
from attrs import validators as v

@attr.s
class C:
    x = attr.ib(validator=v.deep_iterable([v.instance_of(int), v.ge(2)], [v.instance_of(list), v.min_len(1)]))

print(C([3]))
try:
    C([])
except ValueError as e:
    print("empty list ->", e)
try:
    C([1])
except ValueError as e:
    print("member fails ->", e)

@attr.s
class D:
    m = attr.ib(validator=v.deep_mapping((v.instance_of(str), v.min_len(1)), [v.instance_of(int)], (v.instance_of(dict), v.max_len(2))))

print(D({"ab": 1}))
try:
    D({})
except TypeError as e:
    print("bad key ->", e)
try:
    D({"a": 1, "b": 2, "c": 3})
except ValueError as e:
    print("mapping fails ->", e)

print(repr(v.deep_iterable([v.instance_of(int)], [v.instance_of(list)])))
print(repr(v.deep_mapping([v.instance_of(str)], [v.instance_of(int)], [v.instance_of(dict)])))
# hashability preserved
print(hash(v.deep_iterable([v.instance_of(int)], [v.instance_of(list)])) is not None)
print(hash(v.deep_mapping([v.instance_of(str)], [v.instance_of(int)], [v.instance_of(dict)])) is not None)
EOF
